mermaid_diagrams.diagram_code:
graph TD
    A[Start] --> B(1. Clarification);
    B --> B_D(DIVERGE: Explore the Mess);
    B_D --> B_C(CONVERGE: Identify the Core Problem);

    B_C --> C(2. Ideation);
    C --> C_D(DIVERGE: Generate Ideas - Brainstorming);
    C_D --> C_C(CONVERGE: Select Promising Ideas);

    C_C --> D(3. Development);
    D --> D_D(DIVERGE: Explore Solutions);
    D_D --> D_C(CONVERGE: Formulate a Plan);

    D_C --> E(4. Implementation);
    E --> E_D(DIVERGE: Identify Resources & Obstacles);
    E_D --> E_C(CONVERGE: Create Action Plan);
    E_C --> F[Finish];

    style B_D fill:#cff,stroke:#333,stroke-width:2px
    style C_D fill:#cff,stroke:#333,stroke-width:2px
    style D_D fill:#cff,stroke:#333,stroke-width:2px
    style E_D fill:#cff,stroke:#333,stroke-width:2px

    style B_C fill:#fcf,stroke:#333,stroke-width:2px
    style C_C fill:#fcf,stroke:#333,stroke-width:2px
    style D_C fill:#fcf,stroke:#333,stroke-width:2px
    style E_C fill:#fcf,stroke:#333,stroke-width:2px
